BEGIN;
SET LOCAL lock_timeout='5s';
LOCK TABLE standards,criteria,compliances,evidence,"complianceAssessments","complianceEvidenceChecks","surveyorReports","surveyorReportReopens","surveyorStandardSummaries","surveyStandardAssignments","surveyToolkitSnapshotCompliances","surveyToolkitTemplateCompliances" IN SHARE ROW EXCLUSIVE MODE;
CREATE TABLE standard1_backup_20260925 (table_name text NOT NULL, row_data jsonb NOT NULL);
CREATE TEMP TABLE old_c AS SELECT * FROM criteria WHERE "standardId"=1;
CREATE TEMP TABLE old_co AS SELECT co.* FROM compliances co JOIN old_c USING("criterionId");
CREATE TEMP TABLE old_a AS SELECT a.* FROM "complianceAssessments" a JOIN old_co USING("complianceId");
CREATE TEMP TABLE affected AS SELECT DISTINCT "surveyId","surveyorId" FROM old_a;
CREATE TEMP TABLE full_surveys AS SELECT "surveyId",min("surveyorId") AS "surveyorId" FROM old_a GROUP BY "surveyId" HAVING count(DISTINCT "complianceId")=49 AND count(DISTINCT "surveyorId")=1;
CREATE TEMP TABLE full_snapshots AS SELECT "surveyToolkitSnapshotId" FROM "surveyToolkitSnapshotCompliances" WHERE "complianceId" IN (SELECT "complianceId" FROM old_co) GROUP BY "surveyToolkitSnapshotId" HAVING count(DISTINCT "complianceId")=49;
CREATE TEMP TABLE full_templates AS SELECT "surveyToolkitTemplateId" FROM "surveyToolkitTemplateCompliances" WHERE "complianceId" IN (SELECT "complianceId" FROM old_co) GROUP BY "surveyToolkitTemplateId" HAVING count(DISTINCT "complianceId")=49;
CREATE TEMP TABLE other_work AS SELECT * FROM "complianceAssessments" WHERE "complianceId" NOT IN (SELECT "complianceId" FROM old_co);
INSERT INTO standard1_backup_20260925 SELECT 'standards',to_jsonb(t) FROM "standards" t WHERE "standardId"=1;
INSERT INTO standard1_backup_20260925 SELECT 'criteria',to_jsonb(t) FROM "criteria" t WHERE "standardId"=1;
INSERT INTO standard1_backup_20260925 SELECT 'compliances',to_jsonb(t) FROM "compliances" t WHERE "complianceId" IN (SELECT "complianceId" FROM old_co);
INSERT INTO standard1_backup_20260925 SELECT 'evidence',to_jsonb(t) FROM "evidence" t WHERE "complianceId" IN (SELECT "complianceId" FROM old_co);
INSERT INTO standard1_backup_20260925 SELECT 'complianceAssessments',to_jsonb(t) FROM "complianceAssessments" t WHERE "complianceAssessmentId" IN (SELECT "complianceAssessmentId" FROM old_a);
INSERT INTO standard1_backup_20260925 SELECT 'complianceEvidenceChecks',to_jsonb(t) FROM "complianceEvidenceChecks" t WHERE "complianceAssessmentId" IN (SELECT "complianceAssessmentId" FROM old_a);
INSERT INTO standard1_backup_20260925 SELECT 'surveyorStandardSummaries',to_jsonb(t) FROM "surveyorStandardSummaries" t WHERE "standardId"=1;
INSERT INTO standard1_backup_20260925 SELECT 'surveyorReports',to_jsonb(t) FROM "surveyorReports" t WHERE ("surveyId","surveyorId") IN (SELECT * FROM affected);
INSERT INTO standard1_backup_20260925 SELECT 'surveyToolkitSnapshotCompliances',to_jsonb(t) FROM "surveyToolkitSnapshotCompliances" t WHERE "complianceId" IN (SELECT "complianceId" FROM old_co);
INSERT INTO standard1_backup_20260925 SELECT 'surveyToolkitTemplateCompliances',to_jsonb(t) FROM "surveyToolkitTemplateCompliances" t WHERE "complianceId" IN (SELECT "complianceId" FROM old_co);
